begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('00000000-0000-4000-8000-000000009801');
insert into public.users(id) values('00000000-0000-4000-8000-000000009801') on conflict do nothing;
insert into public.workspaces(id,name,personal,creator_id) values('00000000-0000-4000-8000-000000009811','Recurrence fixture',false,'00000000-0000-4000-8000-000000009801');
insert into public.workspace_members(ws_id,user_id,type) values('00000000-0000-4000-8000-000000009811','00000000-0000-4000-8000-000000009801','MEMBER') on conflict do nothing;
update public.workspace_default_permissions set enabled=true where ws_id='00000000-0000-4000-8000-000000009811' and permission='manage_calendar';
insert into public.workspace_default_permissions(ws_id,permission,enabled) select '00000000-0000-4000-8000-000000009811','manage_calendar',true where not exists(select 1 from public.workspace_default_permissions where ws_id='00000000-0000-4000-8000-000000009811' and permission='manage_calendar');
create function public.fixture_series(action text,input jsonb default '{}') returns jsonb language sql as $$
 select public.calendar_series_operation('00000000-0000-4000-8000-000000009811',action,jsonb_build_object('intentHash',md5(input::text))||input);
$$;
create function public.fixture_series_input() returns jsonb language sql as $$
 select '{"intentHash":"synthetic-create","requestId":"00000000-0000-4000-8000-000000009821","rule":{"version":1,"frequency":"daily","interval":1,"timeZone":"UTC","end":{"type":"count","count":5}},"anchor":{"startLocal":"2026-10-05T09:00:00","endLocal":"2026-10-05T10:00:00","allDay":false},"payload":{"title":"Synthetic","description":"","is_encrypted":false}}'::jsonb;
$$;
select throws_ok($$select public.fixture_series('create',public.fixture_series_input())$$,'42501',null,'anonymous cannot create');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000009801',true);
select throws_ok($$select public.fixture_series('create',public.fixture_series_input()||'{"requestId":"00000000-0000-4000-8000-000000009829","intentHash":"invalid-rule","rule":{"version":1,"frequency":"daily","interval":0}}'::jsonb)$$,'23514',null,'direct malformed rule fails database constraint');
create temporary table created_series as select public.fixture_series('create',public.fixture_series_input()) as data;
select is((select data->>'revision' from created_series),'1','create establishes revision');
select is(public.fixture_series('create',public.fixture_series_input()),(select data from created_series),'replay returns original receipt');
select is((select count(*)::integer from private.calendar_event_series),1,'replay does not duplicate series');
select throws_ok($$select public.fixture_series('create',public.fixture_series_input()||'{"intentHash":"different","payload":{"title":"Changed"}}'::jsonb)$$,'22023',null,'request id binds the original payload');
select throws_ok($$select public.fixture_series('update',jsonb_build_object('requestId','00000000-0000-4000-8000-000000009822','seriesId',(select data->>'id' from created_series),'expectedRevision',2,'scope','this','originalStartLocal','2026-10-06T09:00:00','exception','{}'::jsonb))$$,'40001',null,'stale revision rejects writes');
select is(public.fixture_series('delete',jsonb_build_object('requestId','00000000-0000-4000-8000-000000009823','seriesId',(select data->>'id' from created_series),'expectedRevision',1,'scope','this','originalStartLocal','2026-10-06T09:00:00'))->>'revision','2','cancel instance increments revision');
select is((select exception->>'cancelled' from private.calendar_event_series_exceptions),'true','cancellation preserves original slot');
select is(public.fixture_series('update',jsonb_build_object('requestId','00000000-0000-4000-8000-000000009824','seriesId',(select data->>'id' from created_series),'expectedRevision',2,'scope','future','originalStartLocal','2026-10-06T09:00:00','previousRule',public.fixture_series_input()->'rule'||'{"end":{"type":"until","date":"2026-10-05"}}'::jsonb,'rule',public.fixture_series_input()->'rule','anchor',public.fixture_series_input()->'anchor','payload',public.fixture_series_input()->'payload'))->>'discardedFutureExceptions','1','future split removes future exceptions transactionally');
select is((select count(*)::integer from private.calendar_event_series),2,'future split creates one new series');
select is((select count(*)::integer from public.workspace_calendar_events where ws_id='00000000-0000-4000-8000-000000009811'),0,'virtual series never materialize duplicate event rows');
select throws_ok($$select public.calendar_series_operation('00000000-0000-4000-8000-000000009811','read','{}','00000000-0000-4000-8000-000000009899')$$,'42501',null,'authenticated actor cannot spoof another actor');
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claim.role','service_role',true);
select is(jsonb_array_length(public.calendar_series_operation('00000000-0000-4000-8000-000000009811','read','{}','00000000-0000-4000-8000-000000009801')),2,'verified satellite actor uses service-role client');
select throws_ok($$select public.calendar_series_operation('00000000-0000-4000-8000-000000009811','read','{}','00000000-0000-4000-8000-000000009899')$$,'42501',null,'service actor still requires workspace membership');
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000009899',true);
select throws_ok($$select public.fixture_series('read')$$,'42501',null,'another actor cannot read');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000009801',true);
delete from public.workspace_members where ws_id='00000000-0000-4000-8000-000000009811' and user_id='00000000-0000-4000-8000-000000009801';
select throws_ok($$select public.fixture_series('read')$$,'42501',null,'membership revocation applies to reads');
select ok(not has_table_privilege('authenticated','private.calendar_event_series','SELECT'),'authenticated has no direct private table access');
select ok(not has_function_privilege('anon','public.calendar_series_operation(uuid,text,jsonb,uuid)','EXECUTE'),'anonymous has no RPC grant');
select * from finish();
rollback;
